"""Prelumo dashboard: a sidebar panel generated by a Lovelace strategy shipped with the integration.

The panel's config is only ``{"strategy": {"type": "custom:prelumo", ...}}`` - the views are built in
the browser by ``frontend/prelumo-strategy.js`` from the entity ids passed here, so the dashboard
follows every release and needs no editing.
"""

from __future__ import annotations

import logging
from pathlib import Path
from typing import Any

from homeassistant.components import frontend
from homeassistant.components.http import StaticPathConfig
from homeassistant.core import HomeAssistant
from homeassistant.helpers import entity_registry as er
from homeassistant.helpers.json import json_fragment, json_bytes

from .const import CONF_RCE_TODAY, CONF_RCE_TOMORROW, DOMAIN

_LOGGER = logging.getLogger(__name__)

URL_PATH = "prelumo"
STATIC_URL = f"/{DOMAIN}_static"
JS_FILE = "prelumo-strategy.js"
_REGISTERED = f"{DOMAIN}_frontend_registered"

# entity keys the strategy uses: (platform, key)
_KEYS = [
    ("sensor", "proposed_plan"), ("sensor", "active_slot"), ("sensor", "next_change"),
    ("sensor", "expected_savings"), ("sensor", "shadow_savings"), ("sensor", "last_full_charge"),
    ("sensor", "ev_energy_needed"), ("sensor", "load_forecast"), ("sensor", "pv_forecast_corrected"),
    ("select", "strategy"), ("switch", "auto_mode"), ("switch", "shadow_mode"),
    ("switch", "grid_arbitrage"), ("binary_sensor", "fallback_active"),
    ("binary_sensor", "full_charge_due"), ("binary_sensor", "grid_outage"),
    ("binary_sensor", "sell_now"),
]


def _strategy(hass: HomeAssistant, coord: Any) -> dict[str, Any]:
    reg = er.async_get(hass)
    entry_id = coord.config_entry.entry_id
    ents = {}
    for platform, key in _KEYS:
        ents[key] = reg.async_get_entity_id(platform, DOMAIN, f"{entry_id}_{key}") or f"{platform}.{DOMAIN}_{key}"
    inv = coord.inv
    return {
        "type": f"custom:{DOMAIN}",
        "entities": ents,
        "inverter": {
            "soc": inv.soc, "battery_power": inv.battery_power, "grid_power": inv.s("siec_moc"),
            "house": inv.house, "mode_select": coord.writer.mode_select,
        },
        "rce": {"today": coord.conf.get(CONF_RCE_TODAY), "tomorrow": coord.conf.get(CONF_RCE_TOMORROW)},
    }


class _PrelumoLovelace:
    """Read-only Lovelace config for the panel (duck-types lovelace.dashboard.LovelaceConfig)."""

    mode = "yaml"

    def __init__(self, hass: HomeAssistant, coord: Any) -> None:
        self.hass = hass
        self._coord = coord
        self.config = {"url_path": URL_PATH, "mode": "yaml", "title": "Prelumo"}

    @property
    def url_path(self) -> str:
        return URL_PATH

    def _cfg(self) -> dict[str, Any]:
        return {"strategy": _strategy(self.hass, self._coord)}

    async def async_get_info(self) -> dict[str, Any]:
        return {"mode": self.mode, "views": 0}

    async def async_load(self, force: bool) -> dict[str, Any]:
        return self._cfg()

    async def async_json(self, force: bool) -> json_fragment:
        return json_fragment(json_bytes(self._cfg()))

    async def async_save(self, config: dict[str, Any]) -> None:
        from homeassistant.exceptions import HomeAssistantError
        raise HomeAssistantError("The Prelumo dashboard is generated by the integration")

    async def async_delete(self) -> None:
        from homeassistant.exceptions import HomeAssistantError
        raise HomeAssistantError("The Prelumo dashboard is removed with the integration")


async def async_setup_dashboard(hass: HomeAssistant, coord: Any, version: str) -> None:
    """Serve the strategy module and register the sidebar panel. Never fails the setup."""
    try:
        if not hass.data.get(_REGISTERED):
            path = Path(__file__).parent / "frontend"
            await hass.http.async_register_static_paths([StaticPathConfig(STATIC_URL, str(path), False)])
            frontend.add_extra_js_url(hass, f"{STATIC_URL}/{JS_FILE}?v={version}")
            hass.data[_REGISTERED] = True
        from homeassistant.components.lovelace.const import LOVELACE_DATA

        data = hass.data.get(LOVELACE_DATA)
        if data is None:
            _LOGGER.warning("Lovelace not loaded - Prelumo dashboard not registered")
            return
        if URL_PATH in data.dashboards and not isinstance(data.dashboards[URL_PATH], _PrelumoLovelace):
            _LOGGER.warning("A dashboard at /%s already exists - Prelumo dashboard not registered", URL_PATH)
            return
        data.dashboards[URL_PATH] = _PrelumoLovelace(hass, coord)
        frontend.async_register_built_in_panel(
            hass, "lovelace", sidebar_title="Prelumo", sidebar_icon="mdi:white-balance-sunny",
            frontend_url_path=URL_PATH, config={"mode": "yaml"}, require_admin=False, update=True,
        )
    except Exception:  # noqa: BLE001 - the dashboard is optional, planning must keep running
        _LOGGER.exception("Prelumo dashboard could not be registered")


def async_remove_dashboard(hass: HomeAssistant) -> None:
    try:
        from homeassistant.components.lovelace.const import LOVELACE_DATA

        data = hass.data.get(LOVELACE_DATA)
        if data is not None and isinstance(data.dashboards.get(URL_PATH), _PrelumoLovelace):
            data.dashboards.pop(URL_PATH)
            frontend.async_remove_panel(hass, URL_PATH, warn_if_unknown=False)
    except Exception:  # noqa: BLE001
        _LOGGER.exception("Prelumo dashboard could not be removed")
